import {opportunitiesPanel} from './career-opportunities-ui.js';
import {cloneExperiment,changeExperimentFamily,editExperimentAnswer,originalExperiment,rerunExperiment,answerChanges} from './developer-experiment.js?v=0.31.0';
import {studentReviewInputs} from './developer-review-data.js?v=0.31.0';
import {renderIntermediate,renderCareers,renderPlan,renderComparison} from './developer-experiment-ui.js?v=0.31.0';
import {careerFamilies} from './guide-state.js?v=0.31.0';
import {occupations} from './occupation-data.js?v=0.31.0';
import {profileQuestions} from './profile-journey.js?v=0.31.0';
import {escapeHTML as h} from './model.js?v=0.31.0';
const dataNode=document.querySelector('#experiment-data');
if(dataNode){
 try{
 const data=JSON.parse(dataNode.textContent);if(!data.state?.profileJourney)throw Error('This case has no editable state.');
 const original=cloneExperiment(data.state);original.profileJourney.family=data.family;
 const before=originalExperiment(original),staticSections=Object.fromEntries(['intermediate','refined','plan','followups'].map(id=>[id,document.getElementById(id).innerHTML]));
 let draft=cloneExperiment(original),editing=false,lastRun=null,dirty=false,runNumber=0;
 const panel=document.querySelector('#experiment-panel'),settings=document.querySelector('#experiment-settings'),status=document.querySelector('#experiment-status'),comparison=document.querySelector('#experiment-comparison');
 const controls={edit:document.querySelector('#edit-experiment'),run:document.querySelector('#run-experiment'),reset:document.querySelector('#reset-experiment'),download:document.querySelector('#download-experiment')};
 const print=document.querySelector('#print-view'),stickyRun=document.querySelector('#run-experiment-sticky'),pendingTag=document.querySelector('#experiment-pending-tag');stickyRun.addEventListener('click',()=>controls.run.click());
 settings.innerHTML=`<div class="experiment-settings"><label>Profession field<select id="experiment-family">${careerFamilies.map(f=>'<option value="'+h(f.id)+'">'+h(f.title)+'</option>').join('')}</select></label><label>Plan preview<select id="experiment-plan"><option value="adapt">Adapt the original plan to supported matches</option>${original.guide.primaryCareer?'<option value="original">Keep the original career as an explicit choice</option>':''}<option value="none">No career plan</option><optgroup label="Explicit career preview">${[...occupations].sort((a,b)=>a.title.localeCompare(b.title)).map(o=>'<option value="career:'+h(o.id)+'">'+h(o.finance?.title||o.title)+'</option>').join('')}</optgroup></select></label><label>Pay stage<select id="experiment-pay"><option value="auto">Keep the original stage, or start paid training / entry</option><option value="entry">Entry level</option><option value="year5">5 years</option><option value="year10">10 years</option><option value="year20">20 years</option></select></label><label>Housing<select id="experiment-housing"><option value="rent">Rent</option><option value="own">Own</option></select></label></div><p>Adapt mode keeps the original career if it is still suggested. If matching answers change and it no longer fits, it previews a single supported career. Multiple supported careers require an explicit choice. An unchanged case retains its original explicit choice.</p><p>Experience, values, and lifestyle do not alter RIASEC scores. Clinical preparation preferences can change which professions are suggested.</p><p>New fields start with unanswered follow-ups. Answers for previously visited fields stay available when you switch back.</p>`;
 if(data.planPolicy==='explicit')settings.querySelector('#experiment-plan').value='none';
 settings.querySelector('#experiment-family').value=draft.profileJourney.family;settings.querySelector('#experiment-housing').value=draft.guide.lifestyleBuilder.homeMode;
 function rows(){return studentReviewInputs(draft);}
 function isMulti(group,q){return group==='followup'||group==='profile'&&(q.kind==='values'||profileQuestions.find(p=>p.id===q.id)?.multi);}
 function editor(group,q){const multi=isMulti(group,q);return `<fieldset class="answer-editor" aria-label="${h(q.prompt)}"><legend>Change answer${multi?(q.kind==='values'?' · choose up to three':' · choose any that fit'):''}</legend>${q.options.map(o=>'<label><input type="'+(multi?'checkbox':'radio')+'" name="experiment-'+h(group)+'-'+h(q.id)+'" data-edit-group="'+group+'" data-edit-question="'+h(q.id)+'" value="'+h(o.value)+'" '+(o.selected?'checked':'')+'> '+h(o.label)+'</label>').join('')}${group==='followup'?'<button type="button" data-unsure-question="'+h(q.id)+'">Not sure yet / clear choices</button>':''}</fieldset>`;}
 function updateDisplayedAnswer(row,q){row.querySelector('.answer').textContent='Answer: '+q.answer;const options=row.querySelector('.answer-options');if(options)options.innerHTML=q.options.map(o=>'<li>'+(o.selected?'✓ ':'')+h(o.label)+(o.selected?' <strong>(selected)</strong>':'')+'</li>').join('');}
 function mountEditors(){const input=rows();for(const [group,key]of [['lifestyle','lifestyle'],['profile','profile'],['followup','followups']])for(const q of input[key]){const row=document.querySelector('[data-question="'+q.id+'"]');if(!row)continue;updateDisplayedAnswer(row,q);row.querySelector('.answer-editor')?.remove();row.insertAdjacentHTML('beforeend',editor(group,q));}}
 function renderFollowups(){const input=rows();document.querySelector('#followups').innerHTML='<h2>4. Profession follow-ups & answers</h2><ol class="questions">'+input.followups.map(q=>'<li value="'+q.number+'" data-question="'+h(q.id)+'"><strong>'+h(q.prompt)+'</strong><p class="answer">Answer: '+h(q.answer)+'</p><ul class="answer-options">'+q.options.map(o=>'<li>'+(o.selected?'✓ ':'')+h(o.label)+'</li>').join('')+'</ul></li>').join('')+'</ol>';}
 function setDirty(message='Answers changed. Rerun matching to update pathways, careers, and the plan.'){dirty=true;if(!comparison.hidden&&!comparison.querySelector('.outdated-note'))comparison.insertAdjacentHTML('afterbegin','<p class="outdated-note"><strong>Previous run — rerun matching to compare your latest answers.</strong></p>');pendingTag.textContent='Rerun needed';status.textContent=message;status.className='experiment-pending';controls.download.disabled=true;print.disabled=true;for(const id of ['intermediate','refined','plan']){const el=document.getElementById(id);el.dataset.outdated='true';if(!el.querySelector('.outdated-note'))el.insertAdjacentHTML('afterbegin','<p class="outdated-note"><strong>Previous results — rerun matching to update.</strong></p>');}}
 controls.edit.disabled=false;controls.reset.disabled=false;status.textContent='Original case shown. Experiments use engine '+before.matchingEngineVersion+'. Select Edit answers to start.';
 controls.edit.addEventListener('click',()=>{editing=!editing;document.body.classList.toggle('experiment-editing',editing);settings.hidden=!editing;controls.run.disabled=!editing;stickyRun.disabled=!editing;stickyRun.hidden=!editing;controls.edit.textContent=editing?'Hide answer editors':'Edit answers';if(editing){mountEditors();if(!dirty&&!lastRun)status.textContent='Edit answers below, then choose Rerun matching.';}});
 document.addEventListener('change',event=>{const input=event.target;if(!input.matches('[data-edit-question]'))return;try{const group=input.dataset.editGroup,id=input.dataset.editQuestion,field=input.closest('fieldset'),numeric=group==='lifestyle'||group==='profile'&&['interest','pathway'].includes(profileQuestions.find(q=>q.id===id)?.kind);const values=[...field.querySelectorAll('input:checked')].map(el=>numeric?Number(el.value):el.value);draft=editExperimentAnswer(draft,group,id,values);const updated=rows()[group==='followup'?'followups':group].find(q=>q.id===id);updateDisplayedAnswer(input.closest('[data-question]'),updated);setDirty();}catch(e){mountEditors();status.textContent=e.message;status.className='experiment-pending';}});
 document.addEventListener('click',event=>{const button=event.target.closest('[data-unsure-question]');if(!button)return;draft=editExperimentAnswer(draft,'followup',button.dataset.unsureQuestion,[]);mountEditors();setDirty();});
 settings.addEventListener('change',event=>{const id=event.target.id;try{if(id==='experiment-family'){draft=changeExperimentFamily(draft,event.target.value);renderFollowups();mountEditors();}if(id==='experiment-housing'){draft=editExperimentAnswer(draft,'housing','homeMode',[event.target.value]);mountEditors();}setDirty(id==='experiment-family'?'Field changed. Complete its follow-ups, then rerun matching.':'Choices changed. Rerun matching to update results.');}catch(e){status.textContent=e.message;status.className='experiment-pending';}});
 controls.run.addEventListener('click',()=>{try{const result=rerunExperiment(original,draft,{planChoice:settings.querySelector('#experiment-plan').value,salaryStage:settings.querySelector('#experiment-pay').value});document.querySelector('#intermediate').innerHTML=renderIntermediate(result);document.querySelector('#refined').innerHTML=renderCareers(result)+opportunitiesPanel(draft,{compact:true,compareOnly:true});document.querySelector('#plan').innerHTML=renderPlan(result);comparison.innerHTML=renderComparison(before,result,answerChanges(original,draft));comparison.hidden=false;for(const id of ['intermediate','refined','plan'])delete document.getElementById(id).dataset.outdated;lastRun=result;document.dispatchEvent(new CustomEvent('fieldguide-lab-rerun',{detail:{state:cloneExperiment(draft)}}));dirty=false;pendingTag.textContent='Results updated';runNumber++;status.textContent='Run '+runNumber+' complete. '+result.pathways.length+' supported pathways; '+result.professions.length+' career '+(result.professions.length===1?'suggestion':'suggestions')+'. '+(result.plan?'Plan preview updated.':'No career plan assigned.');status.className='experiment-complete';controls.download.disabled=false;print.disabled=false;comparison.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){status.textContent='Rerun could not finish: '+e.message;status.className='experiment-pending';}});
 controls.reset.addEventListener('click',()=>{draft=cloneExperiment(original);document.dispatchEvent(new CustomEvent('fieldguide-lab-rerun',{detail:{state:cloneExperiment(original)}}));lastRun=null;dirty=false;pendingTag.textContent='';for(const [id,html]of Object.entries(staticSections)){document.getElementById(id).innerHTML=html;delete document.getElementById(id).dataset.outdated;}settings.querySelector('#experiment-family').value=draft.profileJourney.family;settings.querySelector('#experiment-housing').value=draft.guide.lifestyleBuilder.homeMode;settings.querySelector('#experiment-plan').value=data.planPolicy==='explicit'?'none':'adapt';settings.querySelector('#experiment-pay').value='auto';comparison.hidden=true;comparison.innerHTML='';mountEditors();status.textContent='Original answers and results restored. Your saved guide is unchanged.';status.className='';controls.download.disabled=true;print.disabled=false;});
 controls.download.addEventListener('click',()=>{if(!lastRun||dirty)return;const payload={application:'Fieldguide developer experiment',caseId:data.id,exportedAt:new Date().toISOString(),matchingEngineVersion:lastRun.matchingEngineVersion,planMode:settings.querySelector('#experiment-plan').value,salaryStage:settings.querySelector('#experiment-pay').value,originalState:original,editedState:draft,originalResults:before,rerunResults:lastRun};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='fieldguide-experiment-'+data.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 }catch(e){document.querySelector('#experiment-status').textContent='Experiment tools could not load: '+e.message+'. The original read-only case remains available.';}
}
